export const fmt = {
  currency: (n) => {
    if (n === null || n === undefined || isNaN(n)) return '–';
    return `$${Math.round(n).toLocaleString('zh-TW')}`;
  },
  pct: (n, d = 1) => {
    if (n === null || n === undefined || isNaN(n)) return '–';
    return `${(n * 100).toFixed(d)}%`;
  },
  number: (n) => {
    if (n === null || n === undefined || isNaN(n)) return '–';
    return Math.round(n).toLocaleString('zh-TW');
  },
};
